	[Button(null)]
	public void LoadPlayerProgression()
	{
		if (saveSystem.HasCharacterUnlockedKey(moonieCharacter))
		{
			if (gameController.IsDemo)
			{
				saveSystem.LoadCharacterUnlocked(moonieCharacter);
				saveSystem.LoadCharacterUnlocked(cellariusCharacter);
				saveSystem.LoadFirstTimePlayingWithMoonieAndCellarius();
			}
			else
			{
				saveSystem.LoadPlayerProgression();
			}
		}
		else
		{
			if (gameController.IsDemo)
			{
				saveSystem.LoadFirstTimePlayingWithMoonieAndCellarius();
			}
			UnlockCharacter(moonieCharacter);
			saveSystem.LoadPlayerProgression();
			if (gameController.IsDemo && gameController.IsEventDemo)
			{
				UnlockCharacter(cellariusCharacter);
			}
		}
		for (int i = 0; i < percentageEventSents.Length; i++)
		{
			percentageEventSents[i].percentageEventSent = saveSystem.LoadIsPercentProgressionEventSent(percentageEventSents[i].percentage);
		}
	}

