	public void CalculatePlayerProgressionPercentage()
	{
		PlayerProgressionPercentage = 0f;
		for (int i = 0; i < charactersList.charactersList.Length; i++)
		{
			if (!charactersList.charactersList[i].CharacterEnum)
			{
				charactersList.charactersList[i].SetCharacterPercentageProgression();
				PlayerProgressionPercentage += charactersList.charactersList[i].GetCharacterNonNeutralPercentage() / 6f;
			}
		}
		PlayerProgressionPercentage += achievementsList.GetUnlockedAchievementsPercentage() * (float)achievementsPercentage;
		int allPlayerDiceDiscoveredTotal = allPlayerDicesList.GetAllPlayerDiceDiscoveredTotal();
		int allPlayerDiceTotalWithoutTutorialAndDebug = allPlayerDicesList.GetAllPlayerDiceTotalWithoutTutorialAndDebug();
		float blessingsDiscoveredAmount = omensListsList.GetBlessingsDiscoveredAmount();
		float blessingsTotal = omensListsList.GetBlessingsTotal();
		float sentinelDiscoveredAmount = companionsListsList.GetSentinelDiscoveredAmount();
		float sentinelTotal = companionsListsList.GetSentinelTotal();
		float num = (float)allPlayerDiceDiscoveredTotal + blessingsDiscoveredAmount + sentinelDiscoveredAmount;
		float num2 = (float)allPlayerDiceTotalWithoutTutorialAndDebug + blessingsTotal + sentinelTotal;
		PlayerProgressionPercentage += num / num2 * (float)discoverSystemPercentage;
		PlayerProgressionPercentageAnalytics();
	}

	private void PlayerProgressionPercentageAnalytics()
	{
		if (!saveSystem.HasAgreementSaveKey() || !saveSystem.LoadAgreement())
		{
			return;
		}
		for (int i = 0; i < percentageEventSents.Length; i++)
		{
			if ((float)percentageEventSents[i].percentage <= PlayerProgressionPercentage && !percentageEventSents[i].percentageEventSent)
			{
				saveSystem.SavePercentProgressionEventSent(value: true, percentageEventSents[i].percentage);
				totalPlaytime.LoadStatisticsData("");
				float value = totalPlaytime.data.value;
				Dictionary<string, object> eventParams = new Dictionary<string, object>
				{
					{
						"PlayerProgressionPercentage",
						percentageEventSents[i].percentage
					},
					{ "PlayerProgressionTime", value }
				};
				ReferenceSingleton<AnalyticsManager>.Instance.RecordEventConvertingOldSDK("PlayerProgressionBasedOnPercentage", eventParams);
				AnalyticsService.Instance.Flush();
				Debug.Log("===== Player Progression Percentage Analytics Flushed =====");
				break;
			}
		}
	}

