	}

	private void SetCharacterXP(Character character, int xp)
	{
		character.CharacterProgression.CharacterXP = xp;
		saveSystem.SaveCharacterXP(character, saveAndStoreCache: true);
	}

	private void SetAllCharactersAnomalyAndAstreaLevel(bool maxLevel)
	{
		for (int i = 0; i < unlockedCharactersDevelopment.Count; i++)
		{
			SetCharacterAnomalyAndAstreaLevel(unlockedCharactersDevelopment[i], maxLevel);
		}
	}

	private void SetCharacterAnomalyAndAstreaLevel(Character character, bool maxLevel)
	{
		CharacterProgression characterProgression = character.CharacterProgression;
		characterProgression.UnlockedAnomalyLevel = (maxLevel ? (anomalyLevel.DifficultyLevelDatas.Length - 1) : (-1));
		characterProgression.CurrentAnomalyLevel = ((!maxLevel) ? (-1) : 0);
		saveSystem.SaveCharacterUnlockedAnomalyLevel(character);
		saveSystem.SaveCharacterCurrentAnomalyLevel(character);
		characterProgression.UnlockedAstreaLevel = (maxLevel ? (astreaLevel.DifficultyLevelDatas.Length - 1) : (-1));
		characterProgression.CurrentAstreaLevel = (maxLevel ? 1 : (-1));
		saveSystem.SaveCharacterUnlockedAstreaLevel(character);
		saveSystem.SaveCharacterCurrentAstreaLevel(character);
		characterProgression.MaxNonHiddenAnomalyLevelDefeated = maxLevel;
		characterProgression.MaxNonHiddenAstreaLevelDefeated = maxLevel;
		characterProgression.MaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime = maxLevel;
		characterProgression.AnomalyLevelHiddenDefeated = maxLevel;
		characterProgression.AstreaLevelHiddenDefeated = maxLevel;
		saveSystem.SaveCharacterDifficultyBools(character);
		saveSystem.StoreCachedFile();
	}

	public void EraseAllProgression()
	{
		LockAllCharactersButMoonie();
		SetAllCharactersXP(0);
		SetAllCharactersReachedAstreaHeart(reached: false);
		SetAllCharactersAnomalyAndAstreaLevel(maxLevel: false);
		SetAllCharactersFirstChestPicksCounterToZero();
		omensListsList.SetAllBlessingsToUndiscoveredOrLocked();
		dicesRewardsListsList.SetAllDiceToUndiscoveredOrLocked();
		companionsListsList.SetAllCompanionsToUndiscoveredOrLocked();
		saveSystem.SaveIsDefeatedAstreaAtLeastOnce(value: false);
	}

	private void LockAllCharactersButMoonie()
	{
		for (int i = 0; i < unlockedCharactersDevelopment.Count; i++)
		{
			if (unlockedCharactersDevelopment[i] != moonieCharacter)
			{
				UnlockCharacter(unlockedCharactersDevelopment[i], unlock: false);
			}
		}
