	private void SetAllCharactersFirstChestPicksCounterToZero()
	{
		for (int i = 0; i < unlockedCharactersDevelopment.Count; i++)
		{
			unlockedCharactersDevelopment[i].CharacterProgression.FirstChestPicksCounter = 0;
			saveSystem.SaveCharacterFirstChestPicksCounter(unlockedCharactersDevelopment[i]);
		}
	}

	public void EraseStatistics()
